/**
 * End-to-end smoke: real Electron app, real project, real ingest, real gate.
 *
 * Uses two Night Market takes from ~/Downloads when present (Sam's machine),
 * else falls back to synthetic fixtures generated by the engine test helpers.
 * The gate needs the repo .venv with python/requirements.txt installed; when
 * the engine reports unavailable, the gate step asserts the fail-soft path
 * instead (status 'error' with a reason) so CI without a venv still passes.
 */
import { _electron as electron, type ElectronApplication, type Page } from '@playwright/test'
import { test, expect } from '@playwright/test'
import { execFileSync } from 'child_process'
import { existsSync, mkdtempSync, rmSync } from 'fs'
import { readFile } from 'fs/promises'
import { tmpdir, homedir } from 'os'
import { join, resolve } from 'path'

const REPO = resolve(__dirname, '../..')
let app: ElectronApplication
let page: Page
let workDir: string

function realClips(): string[] {
  const dl = join(homedir(), 'Downloads')
  const picks = ['Night Market Stroll.mp4', 'Night Market Stroll (1).mp4'].map((f) => join(dl, f))
  return picks.every((p) => existsSync(p)) ? picks : []
}

function syntheticClips(dir: string): string[] {
  const venvPy = join(REPO, '.venv', 'bin', 'python')
  const py = existsSync(venvPy) ? venvPy : 'python3'
  execFileSync(py, ['-c',
    `import sys; sys.path.insert(0, ${JSON.stringify(join(REPO, 'python'))});\n` +
    `from tests.fixtures import clean_pan, luma_flicker\n` +
    `clean_pan(${JSON.stringify(join(dir, '12_clean_take.mp4'))})\n` +
    `luma_flicker(${JSON.stringify(join(dir, '12_flicker_take.mp4'))})`,
  ], { cwd: join(REPO, 'python') })
  return [join(dir, '12_clean_take.mp4'), join(dir, '12_flicker_take.mp4')]
}

test.beforeAll(async () => {
  workDir = mkdtempSync(join(tmpdir(), 'ctake-e2e-'))
  app = await electron.launch({
    args: [join(REPO, 'out', 'main', 'index.js')],
    env: { ...process.env, CTAKE_E2E: '1' },
  })
  page = await app.firstWindow()
  await page.waitForLoadState('domcontentloaded')
})

test.afterAll(async () => {
  await app?.close()
  rmSync(workDir, { recursive: true, force: true })
})

test('welcome → create project', async () => {
  await expect(page.getByText(/circle take/i).first()).toBeVisible({ timeout: 15_000 })
  // Create the project through the main-side API (dialogs can't be driven headlessly).
  const projPath = await app.evaluate(async (_e, dir) => {
    const api = (globalThis as Record<string, unknown>).__ctakeMain as {
      createProject(parent: string, name: string): Promise<unknown>
      projectPath(): string | null
    }
    await api.createProject(dir, 'E2E Night Market')
    return api.projectPath()
  }, workDir)
  expect(projPath).toContain('E2E Night Market')
  await expect(page.getByText(/the bin/i).first()).toBeVisible({ timeout: 10_000 })
})

test('ingest takes and bind to a shot', async () => {
  const clips = realClips().length ? realClips() : syntheticClips(workDir)
  const result = await app.evaluate(async (_e, payload) => {
    const api = (globalThis as Record<string, unknown>).__ctakeMain as {
      addShot(s: Record<string, unknown>): Promise<unknown>
      ingest(paths: string[]): Promise<{ added: number; skipped: string[] }>
      state(): { takes: Array<{ id: string; fileName: string; probe?: unknown }> }
    }
    await api.addShot({ name: '12', description: 'e2e shot', characterIds: [] })
    const r = await api.ingest(payload)
    return r
  }, clips)
  expect(result.added).toBe(2)

  // Probe + thumbs land asynchronously; poll the main-side state.
  await expect
    .poll(
      () =>
        app.evaluate(() => {
          const api = (globalThis as Record<string, unknown>).__ctakeMain as {
            state(): { takes: Array<{ probe?: unknown }> }
          }
          return api.state().takes.filter((t) => t.probe).length
        }),
      { timeout: 60_000 },
    )
    .toBe(2)
})

test('gate runs (real engine or fail-soft)', async () => {
  const takes = await app.evaluate(async () => {
    const api = (globalThis as Record<string, unknown>).__ctakeMain as {
      state(): { takes: Array<{ id: string }> }
      runGate(id: string): Promise<void>
    }
    const ids = api.state().takes.map((t) => t.id)
    for (const id of ids) await api.runGate(id)
    return ids
  })
  await expect
    .poll(
      () =>
        app.evaluate(() => {
          const api = (globalThis as Record<string, unknown>).__ctakeMain as {
            state(): { takes: Array<{ gate?: { status: string } }> }
          }
          const done = ['pass', 'flag', 'fail', 'error']
          return api.state().takes.filter((t) => t.gate && done.includes(t.gate.status)).length
        }),
      { timeout: 150_000 },
    )
    .toBe(takes.length)

  const gates = await app.evaluate(() => {
    const api = (globalThis as Record<string, unknown>).__ctakeMain as {
      state(): {
        takes: Array<{
          fileName: string
          gate?: { status: string; error?: string; overall: number }
        }>
      }
    }
    return api.state().takes.map((t) => ({
      file: t.fileName,
      status: t.gate?.status,
      overall: t.gate?.overall,
      error: t.gate?.error,
    }))
  })
  console.log('[e2e] gate results:', JSON.stringify(gates))
  // With a working engine we expect real verdicts; without one, error is legal.
  for (const g of gates) expect(['pass', 'flag', 'fail', 'error']).toContain(g.status)
})

test('circle a take and export FCPXML + reshoot list', async () => {
  const out = join(workDir, 'exports')
  const { mkdirSync } = await import('fs')
  mkdirSync(out, { recursive: true })
  const { fcpxml, reshoot } = await app.evaluate(async (_e, dir) => {
    const api = (globalThis as Record<string, unknown>).__ctakeMain as {
      state(): { takes: Array<{ id: string }> }
      circleTake(id: string, on: boolean): Promise<unknown>
      exportFcpxml(p: string): Promise<string>
      exportReshootList(p: string): Promise<string>
    }
    const first = api.state().takes[0]
    await api.circleTake(first.id, true)
    return {
      fcpxml: await api.exportFcpxml(dir + '/selects.fcpxml'),
      reshoot: await api.exportReshootList(dir + '/reshoots.md'),
    }
  }, out)

  const xml = await readFile(fcpxml, 'utf8')
  expect(xml).toContain('<!DOCTYPE fcpxml>')
  expect(xml).toContain('<fcpxml version="1.11">')
  expect(xml).toContain('<asset-clip')
  expect(xml).toContain('media-rep')
  const md = await readFile(reshoot, 'utf8')
  expect(md.length).toBeGreaterThan(0)
})
